import "reflect-metadata"
import {
  Body,
  Delete,
  Get,
  Param,
  ParseIntPipe,
  Patch,
  Post,
  Query,
  type Type,
} from "@nestjs/common"
import type { Actor } from "../core/types.js"
import { CurrentActor, CurrentOrgId } from "../tenancy/decorators.js"

/** Standard routes generated by `OrgResourceController`. */
export type ResourceRoute =
  | "list"
  | "retrieve"
  | "create"
  | "update"
  | "destroy"
  | "approval"

/** Handler method name used for each route (kept from the 0.1 controllers). */
export const RESOURCE_ROUTE_METHOD = {
  list: "findAll",
  retrieve: "findOne",
  create: "create",
  update: "update",
  destroy: "remove",
  approval: "updateApproval",
} as const satisfies Record<ResourceRoute, string>

export type RouteOptions = {
  /** Extra method decorators (permissions, swagger, throttling…). */
  decorators?: Array<MethodDecorator>
}

/** Surface the generated handlers call on `this.service`. */
export interface ResourceServiceLike {
  list(orgId: string, query: Record<string, unknown>): unknown
  retrieve(orgId: string, id: number): unknown
  create(orgId: string, dto: never, actor: Actor): unknown
  update(orgId: string, id: number, dto: never, actor: Actor): unknown
  destroy(orgId: string, id: number, actor: Actor): unknown
  updateApproval?(orgId: string, id: number, dto: never, actor: Actor): unknown
}

export type RequestContext = {
  route: ResourceRoute
  orgId: string
  actor: Actor
}

export type OrgResourceControllerOptions = {
  /** Body DTO for `POST /` (validated by the global ValidationPipe). */
  create?: Type<unknown>
  /** Body DTO for `PATCH /:id`. */
  update?: Type<unknown>
  /** Query DTO for `GET /`. Omit to accept an unvalidated record (0.1 behaviour). */
  query?: Type<unknown>
  /** Body DTO for `PATCH /:id/approval` (enables the route). */
  approval?: Type<unknown>
  /**
   * Per-route switch / options. `false` removes the route (define your own
   * method with the same name to replace it). `approval` is on only when an
   * `approval` DTO is given.
   */
  routes?: Partial<Record<ResourceRoute, boolean | RouteOptions>>
  /** Decorators applied to every generated route. */
  decorators?: Array<MethodDecorator>
  /**
   * `:id` parsing. `int` (default) → ParseIntPipe (400 on non-integers).
   * `number` → legacy `+id` without a pipe (kept for controllers that had no
   * pipe, so error codes stay identical).
   */
  id?: "int" | "number"
  /** Runs first in every generated handler (e.g. a role check). */
  onRequest?: (ctx: RequestContext) => void
}

/** Instance type of a generated controller base. */
export interface OrgResourceControllerBase {
  readonly service: ResourceServiceLike
}

type ParamDecoratorFn = (target: object, key: string, index: number) => void

type RouteSpec = {
  route: ResourceRoute
  verb: (path?: string) => MethodDecorator
  path?: string
  params: Array<{ decorator: ParamDecoratorFn; type: unknown }>
  handler: (this: OrgResourceControllerBase, ...args: never[]) => unknown
}

/**
 * Controller mixin that generates the standard org-scoped routes:
 *
 * ```ts
 * @Controller('categories')
 * @RequirePermissions(CATALOG_MANAGE)
 * export class CategoriesController extends OrgResourceController({
 *   create: CreateCategoryDto,
 *   update: UpdateCategoryDto,
 *   routes: { list: { decorators: [RequireAnyPermission(CATALOG_MANAGE, POS_ACCESS)] } },
 * }) {
 *   constructor(readonly service: CategoriesService) { super() }
 * }
 * ```
 *
 * `orgId` always comes from the token (`@CurrentOrgId`). `design:paramtypes`
 * is set to the given DTOs, so the global ValidationPipe validates (and
 * whitelists) exactly as a hand-written controller would. Extra routes
 * declared on the subclass are registered before the generated ones, so
 * static paths like `GET low-stock` win over `GET :id`.
 */
export function OrgResourceController(
  options: OrgResourceControllerOptions = {},
): abstract new () => OrgResourceControllerBase {
  abstract class ResourceControllerBase implements OrgResourceControllerBase {
    abstract readonly service: ResourceServiceLike
  }

  const idParam = (): { decorator: ParamDecoratorFn; type: unknown } => ({
    decorator: (options.id === "number"
      ? Param("id")
      : Param("id", ParseIntPipe)) as ParamDecoratorFn,
    type: Number,
  })
  const toId = (id: number | string): number =>
    options.id === "number" ? +id : (id as number)
  const org = { decorator: CurrentOrgId() as ParamDecoratorFn, type: String }
  const actor = { decorator: CurrentActor() as ParamDecoratorFn, type: Object }
  const before = (route: ResourceRoute, orgId: string, a: Actor) =>
    options.onRequest?.({ route, orgId, actor: a })

  const specs: RouteSpec[] = [
    {
      route: "create",
      verb: Post,
      params: [
        org,
        actor,
        { decorator: Body() as ParamDecoratorFn, type: options.create ?? Object },
      ],
      handler: function (this: OrgResourceControllerBase, orgId: string, a: Actor, dto: object) {
        before("create", orgId, a)
        return this.service.create(orgId, { ...dto } as never, a)
      } as never,
    },
    {
      route: "list",
      verb: Get,
      params: [
        org,
        actor,
        { decorator: Query() as ParamDecoratorFn, type: options.query ?? Object },
      ],
      handler: function (this: OrgResourceControllerBase, orgId: string, a: Actor, query: object) {
        before("list", orgId, a)
        const { orgId: _ignored, ...rest } = (query ?? {}) as Record<string, unknown>
        return this.service.list(orgId, rest)
      } as never,
    },
    {
      route: "retrieve",
      verb: Get,
      path: ":id",
      params: [org, actor, idParam()],
      handler: function (this: OrgResourceControllerBase, orgId: string, a: Actor, id: number) {
        before("retrieve", orgId, a)
        return this.service.retrieve(orgId, toId(id))
      } as never,
    },
    {
      route: "approval",
      verb: Patch,
      path: ":id/approval",
      params: [
        org,
        actor,
        idParam(),
        { decorator: Body() as ParamDecoratorFn, type: options.approval ?? Object },
      ],
      handler: function (this: OrgResourceControllerBase, orgId: string, a: Actor, id: number, dto: object) {
        before("approval", orgId, a)
        const svc = this.service
        if (!svc.updateApproval) {
          throw new Error("service.updateApproval is not implemented")
        }
        return svc.updateApproval(orgId, toId(id), dto as never, a)
      } as never,
    },
    {
      route: "update",
      verb: Patch,
      path: ":id",
      params: [
        org,
        actor,
        idParam(),
        { decorator: Body() as ParamDecoratorFn, type: options.update ?? Object },
      ],
      handler: function (this: OrgResourceControllerBase, orgId: string, a: Actor, id: number, dto: object) {
        before("update", orgId, a)
        return this.service.update(orgId, toId(id), { ...dto } as never, a)
      } as never,
    },
    {
      route: "destroy",
      verb: Delete,
      path: ":id",
      params: [org, actor, idParam()],
      handler: function (this: OrgResourceControllerBase, orgId: string, a: Actor, id: number) {
        before("destroy", orgId, a)
        return this.service.destroy(orgId, toId(id), a)
      } as never,
    },
  ]

  const proto = ResourceControllerBase.prototype as unknown as Record<
    string,
    unknown
  >
  for (const spec of specs) {
    const setting = options.routes?.[spec.route]
    const enabled =
      spec.route === "approval"
        ? setting !== false && (setting !== undefined || !!options.approval)
        : setting !== false
    if (!enabled) continue

    const key = RESOURCE_ROUTE_METHOD[spec.route]
    Object.defineProperty(proto, key, {
      value: spec.handler,
      writable: true,
      configurable: true,
      enumerable: false,
    })
    Reflect.defineMetadata(
      "design:paramtypes",
      spec.params.map((p) => p.type),
      proto,
      key,
    )
    spec.params.forEach((p, index) => p.decorator(proto, key, index))
    const descriptor = Object.getOwnPropertyDescriptor(proto, key)!
    const routeDecorators = [
      spec.verb(spec.path),
      ...(options.decorators ?? []),
      ...(typeof setting === "object" ? (setting.decorators ?? []) : []),
    ]
    for (const decorate of routeDecorators) {
      decorate(proto, key, descriptor)
    }
  }

  return ResourceControllerBase
}
